	@Test
	void physicalRowsPreserveTheOrdinaryInitialBindingContract() {
		MapBindingSet base = new MapBindingSet();
		base.addBinding("outer", SimpleValueFactory.getInstance().createLiteral("retained"));
		NativeLmdbQuerySource source = mock(NativeLmdbQuerySource.class);
		AggregateSpec[] specs = { AggregateSpec.star("count") };
		NativeGroupIteration iteration = new NativeGroupIteration(source, SlotPlan.empty(), layout(), new int[0],
				specs, false, base, null, null, false, null);
		try {
			AggState state = new AggState(specs, 0, iteration.aggContext, AggregateDistinctChannels.allHash(specs));
			assertNull(iteration.toBindingSet(null, state, false).getValue("outer"),
					"group output retains only grouping and aggregate bindings");
			assertEquals(iteration.toBindingSet(null, state, false),
					iteration.toPhysicalRow(null, state, false).toBindingSet(),
					"physical grouping must preserve the ordinary renderer's binding domain");
		} finally {
			iteration.close();
		}
	}

	@Test
	void physicalGroupingHonorsProbeDeadlineWithoutCancellingTheQuery() {
		SyntheticValueSource source = SyntheticValueSource.forEvaluation(mock(NativeLmdbQuerySource.class));
		NativeGroupIteration iteration = new NativeGroupIteration(source, SlotPlan.empty(), layout(), new int[0],
				new AggregateSpec[] { AggregateSpec.star("count") }, false, EmptyBindingSet.getInstance(), null, null,
				false, null);
		try (NativeGroupResultCursor cursor = new NativeGroupResultCursor(iteration, source.executionContext(), false);
				var probe = LmdbNativeProbeDeadline.enter(System.nanoTime() - 1L)) {
			assertThrows(LmdbNativeProbeDeadlineExceeded.class, cursor::next,
					"physical group initialization must observe the same independent probe deadline as ordinary dispatch");
			assertFalse(cursor.cancellation().isCancellationRequested());
			assertFalse(source.executionContext().cancellation().isCancellationRequested());
		} finally {
			source.executionContext().close();
		}
	}

	@Test
	void opaqueTableInputRetainsCleanupFailureAfterSuppressionDisabledCancellation() {
		SyntheticValueSource source = SyntheticValueSource.forEvaluation(
				mock(NativeLmdbQuerySource.class, CALLS_REAL_METHODS));
		AtomicInteger closeCalls = new AtomicInteger();
		IllegalStateException closeFailure = new IllegalStateException("opaque group input close failed");
		SlotPlan input = new SlotPlan() {
			@Override
			public RowCursor open(RowState row) {
				return new RowCursor() {
					@Override
					public boolean next() {
						throw KernelQueryCancelledException.INSTANCE;
					}

					@Override
					public void close() {
						closeCalls.incrementAndGet();
						throw closeFailure;
					}
				};
			}

			@Override
			public long producedMask() {
				return 0L;
			}
		};
		NativeCustomAggregate custom = new NativeCustomAggregate(null, null, new NativeBindingSetValueEvaluator[0],
				() -> () -> SimpleValueFactory.getInstance().createLiteral("unused"), false, false);
		NativeGroupIteration iteration = new NativeGroupIteration(source, input, layout(), new int[0],
				new AggregateSpec[] { AggregateSpec.custom("opaque", custom) }, false,
				EmptyBindingSet.getInstance(), null, null, false, null);
		assertFalse(NativeGroupResultCursor.allowsReorderedGrouping(iteration),
				"the custom reducer must retain its encounter order");
		NativeGroupResultCursor cursor = new NativeGroupResultCursor(iteration, source.executionContext(), false);
		try {
			Throwable observed = assertThrows(RuntimeException.class, cursor::next);
			assertSame(closeFailure, observed,
					"the physical table owner must retain the real close error after its pull control");
			assertEquals(1, closeCalls.get(), "the source is closed exactly once");
			assertEquals(0, KernelQueryCancelledException.INSTANCE.getSuppressed().length,
					"the suppression-disabled control remains unmodified");
		} finally {
			cursor.close();
			source.executionContext().close();
		}
	}

	@Test
	void acceptedReaderCanAdvanceBorrowedProducerAfterOwnerCloseRequest() {
		SyntheticValueSource source = SyntheticValueSource.forEvaluation(mock(NativeLmdbQuerySource.class));
		NativeExecutionContext context = source.executionContext();
		NativeGroupIteration iteration = new NativeGroupIteration(source, SlotPlan.empty(), layout(), new int[0],
				new AggregateSpec[] { AggregateSpec.star("count") }, false, EmptyBindingSet.getInstance(), null, null,
				false, null);
		NativeGroupResultCursor cursor = new NativeGroupResultCursor(iteration, context, false);
		NativeExecutionContext.Lease reader = context.retainLease();
		try {
			context.nativeState(new Object(), () -> cursor);
			context.close();
			assertEquals(0L, ((Literal) cursor.next().cell("count").value()).longValue());
			reader.close();
			assertTrue(context.isClosed(),
					"after the accepted reader exits, an idle cached producer cannot retain its owner");
		} finally {
			cursor.close();
			reader.close();
			context.close();
		}
	}

	@Test
	void yieldedCursorPhaseCannotBecomeAnotherEvaluationsAmbientIdentity(@TempDir Path directory) throws Exception {
		String eventName = "org.eclipse.rdf4j.lmdb.NativeExecutionPhase";
		Path path = directory.resolve("yielded-cursor.jfr");
		long evaluationId;
		try (Recording recording = new Recording()) {
			recording.enable(eventName).withThreshold(Duration.ZERO);
			recording.start();
			SyntheticValueSource source = SyntheticValueSource.forEvaluation(mock(NativeLmdbQuerySource.class));
			NativeGroupIteration iteration = new NativeGroupIteration(source, SlotPlan.empty(), layout(), new int[0],
					new AggregateSpec[] { AggregateSpec.star("count") }, false, EmptyBindingSet.getInstance(), null,
					null,
					false, null);
			NativeSortBuffer unrelated = new NativeSortBuffer(1, 2);
			try (NativeGroupResultCursor cursor = new NativeGroupResultCursor(iteration, source.executionContext(),
					true)) {
				evaluationId = cursor.cancellation().evaluationId();
				cursor.next();
				unrelated.append(new long[] { 2L }, 0L);
				unrelated.append(new long[] { 1L }, 1L);
				unrelated.sortedOrder((left, lo, right, ro) -> Long.compare(left[lo], right[ro]));
			} finally {
				unrelated.close();
			}
			recording.stop();
			recording.dump(path);
		}
		var sorts = RecordingFile.readAllEvents(path)
				.stream()
				.filter(event -> event.getEventType().getName().equals(eventName)
						&& event.getString("phase").equals("sort"))
				.toList();
		assertTrue(!sorts.isEmpty());
		assertTrue(sorts.stream().allMatch(event -> event.getLong("evaluationId") != evaluationId),
				"a physical cursor lifetime must not install a ThreadLocal identity across next() yields");
	}

