	@Test
	void physicalSummaryPreservesUnicodeWeightedDistinctAndMergeSemantics() {
		NativeLmdbQuerySource source = mock(NativeLmdbQuerySource.class);
		when(source.idSpace()).thenReturn(source);
		when(source.lazyValue(anyLong(), anyInt())).thenAnswer(call -> SimpleValueFactory.getInstance()
				.createLiteral((long) call.getArgument(0) == 1L ? "\ud83d\ude00\u03bb" : ""));
		AggregateSpec[] specs = {
				AggregateSpec.groupConcat("all", 1, false, "\ud83d\ude00")
						.withResultDemand(NativeAggregateResultDemand.LEXICAL_LENGTH),
				AggregateSpec.groupConcat("distinct", 1, true, "\ud83d\ude00")
						.withResultDemand(NativeAggregateResultDemand.LEXICAL_LENGTH) };
		AggContext context = new AggContext(source, true, true);
		try {
			AggregateDistinctChannels channels = AggregateDistinctChannels.allHash(specs);
			AggState left = new AggState(specs, 4, context, channels);
			AggState right = new AggState(specs, 4, context, channels);
			RowState row = new RowState(source, layout(), EmptyBindingSet.getInstance());
			assertTrue(NativeRowSeeder.seed(row.slots, row.layout, row.base, source));
			assertTrue(row.bind(1, 1L));
			left.add(row, 3L);
			right.add(row, 2L);
			row.rollback(0);
			assertTrue(row.bind(1, 2L));
			right.add(row, 1L);
			left.mergeFrom(right);
			assertEquals(15L, left.concatLengths[0], "five two-codepoint inputs plus five eligible separators");
			assertEquals(3L, left.concatLengths[1], "two RDF-distinct inputs include the eligible empty string");
			assertNull(left.concats[0]);
			assertNull(left.concats[1]);
			NativeGroupIteration iteration = new NativeGroupIteration(source, SlotPlan.empty(), row.layout,
					new int[0], specs, false, EmptyBindingSet.getInstance(), null, null, false, null);
			try {
				NativeResultRow physical = iteration.toPhysicalRow(null, left, true);
				assertEquals(15L, physical.cell("all").codePointLength());
				assertThrows(IllegalStateException.class, () -> iteration.toBindingSet(null, left, true));
			} finally {
				iteration.close();
			}
		} finally {
			context.close();
		}
	}

	private static NativeSlotLayout layout() {
		NativeSlotLayout layout = new NativeSlotLayout(Map.of("group", 0, "value", 1), null);
		layout.freeze(List.of("group", "value"));
		return layout;
	}
